const sum=items=>items.reduce((a,i)=>a+cents(i.total),0)/100;
const statuses=['รับออเดอร์','กำลังทำ','เสร็จแล้ว'];
let s,u,epoch=0;
function iso(t=s.now){return new Date(t+7*3600000).toISOString().slice(0,19)+'+07:00';}
function day(t=s.now){return iso(t).slice(0,10);}
function reset(){
 epoch++;
 s={menus:clone(seed.menus),ingredients:clone(seed.ingredients),mappings:clone(seed.ingredient_mappings),accounts:seed.staff.map(a=>({...a,pin:seed.demo_pin,failures:0,lockedUntil:0})),tables:clone(seed.tables),sessions:[],orders:[],items:[],payments:[],paymentEvents:[],statusEvents:[],now:Date.parse(seed.clock.initial),promptpay:seed.promptpay_enabled,nextOrder:1,nextSession:1,nextMenu:9,nextOption:1,nextItem:1,takeawayDay:dayFromSeed(),takeawaySequence:0};
 u={role:'customer',user:null,page:'',auth:'',loginUser:'demokitchen',mode:'dine-in',table:'01',session:null,takeawayCart:[],takeawayOpened:false,selectedMenu:null,selectedOptions:[],slot:null,orderMessage:'',frontTable:'01',ingredient:'rice',mappingMenu:'m01',mappingScope:'whole',mappingOption:'extra-egg',mappingIngredient:'rice',mappingMessage:'',adminId:'new',draft:null,adminMessage:'',accountMessage:'',frontMessage:''};
 history.replaceState(null,'',location.pathname+location.search);render();
}
function dayFromSeed(){return seed.clock.initial.slice(0,10);}
function can(area){return !!u.user&&(u.user.role==='manager'||u.user.role===area);}
function deny(){u.auth='ปฏิเสธ: บัญชีนี้ไม่มีสิทธิ์เข้าหน้านี้ (PIN/สิทธิ์จำลอง)';render();}
function session(){return s.sessions.find(x=>x.id===u.session);}
function currentCart(){return u.mode==='takeaway'?u.takeawayCart:(session()?.cart??[]);}
function sessionOrders(){return s.orders.filter(o=>u.mode==='takeaway'?o.channel==='takeaway':o.session_id===u.session&&session()?.state==='open');}
function latest(){return sessionOrders().at(-1);}
function payment(o){return s.payments.find(p=>p.order_id===o?.id);}
function orderItems(o){return s.items.filter(i=>i.order_id===o.id);}
function blocked(menuId,scope,optionId=null){return s.mappings.some(m=>m.menu_id===menuId&&m.scope===scope&&(scope==='whole'||m.option_id===optionId)&&!s.ingredients.find(i=>i.id===m.ingredient_id)?.available);}
function menuAvailable(m){return !!m&&m.available&&!blocked(m.id,'whole');}
function optionAvailable(m,o){return menuAvailable(m)&&!blocked(m.id,'option',o.id);}
function choices(rows,selected,key='id',label='name'){return rows.map(r=>`<option value="${esc(r[key])}" ${r[key]===selected?'selected':''}>${esc(r[label])}</option>`).join('');}
function button(testid,label,action,extra=''){return `<button ${testid?`data-testid="${testid}"`:''} data-action="${action}" ${extra}>${label}</button>`;}
function slots(){const start=Math.ceil((s.now+20*60000)/(15*60000))*15*60000;return Array.from({length:8},(_,i)=>{const t=start+i*15*60000;return {t,value:iso(t).slice(11,16)+'-'+iso(t+15*60000).slice(11,16),date:day(t)};});}
