function login(){const a=s.accounts.find(a=>a.username===val('staff-user')),pin=val('staff-pin');u.loginUser=val('staff-user');u.user=null;if(!a){u.auth='ปฏิเสธ: ไม่พบบัญชีจำลอง';return render();}if(a.lockedUntil>s.now){u.auth='ปฏิเสธ: บัญชีถูกล็อก 5 นาที ถึง '+iso(a.lockedUntil);return render();}if(a.lockedUntil){a.failures=0;a.lockedUntil=0;}if(a.pin!==pin){a.failures++;if(a.failures>=5){a.lockedUntil=s.now+300000;u.auth='ปฏิเสธ: PIN ผิด 5 ครั้ง บัญชีถูกล็อก 5 นาที ถึง '+iso(a.lockedUntil);}else u.auth=`ปฏิเสธ: PIN ไม่ถูกต้อง (${a.failures}/5)`;return render();}a.failures=0;if(u.role==='manager'&&a.role!=='manager'){u.auth='ปฏิเสธ: ต้องใช้บัญชีผู้จัดการจำลอง';return render();}u.user={username:a.username,role:a.role};u.auth='เข้าใช้สำเร็จ: '+a.username+' · PIN/สิทธิ์จำลอง';if(u.role==='manager'){navigate('menu');}else{u.page=a.role==='front'?'front':'kitchen';render();}}
function navigate(page){if(['menu','mapping','accounts','reports'].includes(page)){if(!can('manager'))return deny();u.role='manager';u.page=page;history.pushState(null,'','#/manager/'+page);}else{if(!can(page))return deny();u.page=page;history.replaceState(null,'','#/'+(u.role==='manager'?'manager':'staff')+'/'+page);}render();}
function handleRoute(){const route=location.hash.slice(1);if(route.startsWith('/manager/')){if(!can('manager')){u.auth='ปฏิเสธ: ไม่มีสิทธิ์เข้าหน้าผู้จัดการผ่าน URL (จำลอง)';if(u.role!=='customer')u.page='';return render();}const page=route.split('/')[2];u.role='manager';u.page=['menu','mapping','accounts','reports','kitchen','front'].includes(page)?page:'';render();}else if(route.startsWith('/staff/')){const page=route.split('/')[2];if(!['kitchen','front'].includes(page)||!can(page)){u.page='';return deny();}u.page=page;render();}}
function selectRole(role){epoch++;u.user=null;u.role=role;u.page='';u.auth='';u.draft=null;u.adminMessage='';u.loginUser=role==='manager'?'demomanager':'demokitchen';history.replaceState(null,'',location.pathname+location.search);render();}
function addItem(){const m=s.menus.find(x=>x.id===u.selectedMenu);if(!menuAvailable(m)||m.options.some(o=>u.selectedOptions.includes(o.id)&&!optionAvailable(m,o))){u.orderMessage='ปฏิเสธ: เมนูหรือตัวเลือกหมด / ปิดขาย';return render();}const options=m.options.filter(x=>u.selectedOptions.includes(x.id)).map(clone);const item={menu_id:m.id,name:m.name,price:m.price,options,total:(cents(m.price)+options.reduce((n,x)=>n+cents(x.price),0))/100};currentCart().push(item);u.orderMessage='เพิ่มลงตะกร้าแล้ว';render();}
function submitOrder(){const cart=currentCart();if(u.mode==='dine-in'&&session()?.state!=='open'){u.orderMessage='ปฏิเสธ: session โต๊ะปิดแล้ว กรุณาเปิดเมนูใหม่';return render();}if(!cart.length){u.orderMessage='กรุณาเพิ่มอาหารลงตะกร้า';return render();}
 // Validate the entire basket before issuing any order, item, payment or queue entry.
 const invalid=cart.find(i=>{const m=s.menus.find(m=>m.id===i.menu_id);return !menuAvailable(m)||i.options.some(o=>!m.options.some(x=>x.id===o.id)||!optionAvailable(m,o));});
 if(invalid){u.orderMessage='ปฏิเสธ: '+invalid.name+' หรือวัตถุดิบ/ตัวเลือกหมด ถูกปิดขาย หรือถูกลบ กรุณานำรายการออกแล้วเลือกใหม่';return render();}
 // Mock policy: refresh a stale catalog price for review, requiring another submit.
 let changed=false;for(const i of cart){const m=s.menus.find(m=>m.id===i.menu_id),options=i.options.map(o=>clone(m.options.find(x=>x.id===o.id)));const total=(cents(m.price)+options.reduce((n,x)=>n+cents(x.price),0))/100;if(i.price!==m.price||i.name!==m.name||JSON.stringify(i.options)!==JSON.stringify(options)){Object.assign(i,{name:m.name,price:m.price,options,total});changed=true;}}
 if(changed){u.orderMessage='ราคา/รายละเอียดเปลี่ยนแล้ว กรุณาตรวจตะกร้าและกดส่งอีกครั้ง (นโยบายจำลอง)';return render();}
 const slot=u.mode==='takeaway'?slots().find(x=>x.t===u.slot):null;if(u.mode==='takeaway'&&!slot){u.orderMessage='ช่วงรับเดิมผ่านเวลาแล้ว กรุณาเลือกช่วงรับใหม่อย่างน้อย 20 นาที';ensureSlot();return render();}
 let takeaway_id=null;if(u.mode==='takeaway'){if(s.takeawayDay!==day()){s.takeawayDay=day();s.takeawaySequence=0;}takeaway_id='T-'+String(++s.takeawaySequence).padStart(3,'0');}
 const o={id:s.nextOrder++,channel:u.mode,table_id:u.mode==='dine-in'?session().table_id:'takeaway',session_id:u.mode==='dine-in'?u.session:null,received_at:iso(Math.floor(s.now/1000)*1000),confirmed_at:iso(),status:0,total:sum(cart),takeaway_id,pickup_slot:slot?.value??null,pickup_date:slot?.date??null};
 s.orders.push(o);for(const i of cart)s.items.push({...clone(i),id:s.nextItem++,order_id:o.id});s.payments.push({order_id:o.id,total:o.total,state:'ยังไม่จ่าย',method:null,requested_at:null});s.paymentEvents.push({order_id:o.id,actor:'ลูกค้าจำลอง',at:iso(),action:'ออเดอร์ใหม่ · ยังไม่จ่าย'});cart.splice(0);u.orderMessage='ส่งออเดอร์ #'+o.id+' แล้ว • แจ้งครัวจำลอง';render();
}
function choosePayment(method,id){const o=id?s.orders.find(o=>o.id===Number(id)):latest();if(!o||!sessionOrders().includes(o))return;const p=payment(o);if(p.state==='จ่ายแล้ว')return;if(method==='promptpay'&&!s.promptpay)return render();p.method=method;if(method==='promptpay'){p.state='ค้างจ่าย';if(p.requested_at===null)p.requested_at=s.now;}else p.state='ยังไม่จ่าย';s.paymentEvents.push({order_id:o.id,actor:'ลูกค้าจำลอง',at:iso(),action:'เลือก '+(method==='cash'?'เงินสด (ยังไม่รับเงิน)':'PromptPay จำลอง · ค้างจ่าย')});render();}
function confirmPayment(id,method){if(!can('front'))return deny();const p=s.payments.find(p=>p.order_id===Number(id));if(!p||p.state==='จ่ายแล้ว'||(method==='slip'&&p.requested_at===null))return;p.state='จ่ายแล้ว';p.method=method==='slip'?'promptpay':'cash';s.paymentEvents.push({order_id:p.order_id,actor:u.user.username,at:iso(),action:method==='slip'?'ยืนยันสลิปจำลอง · จ่ายแล้ว':'รับเงินสดจำลอง · จ่ายแล้ว'});render();}
function validPrice(v){return String(v).trim()!==''&&Number.isFinite(Number(v))&&Number(v)>=0&&Number(v)<=Number.MAX_SAFE_INTEGER/100&&Number.isSafeInteger(Math.round(Number(v)*100));}
function addOption(){const d=u.draft;if(!d.pendingName.trim()||!validPrice(d.pendingPrice)){u.adminMessage='ปฏิเสธ: กรุณาระบุชื่อตัวเลือกและราคาเพิ่ม ≥ 0';return false;}if(d.options.length>=10){u.adminMessage='ปฏิเสธ: ตัวเลือกได้ไม่เกิน 10 รายการ';return false;}d.options.push({id:'opt-'+s.nextOption++,name:d.pendingName.trim(),price:cents(d.pendingPrice)/100});d.pendingName='';d.pendingPrice='0';return true;}
function saveMenu(){if(!can('manager'))return deny();const d=u.draft;if(d.imageLoading||d.imageError){u.adminMessage='ปฏิเสธ: รอรูปอ่านเสร็จหรือเลือกรูปใหม่ที่ถูกต้อง';return render();}if(!d.name.trim()||!validPrice(d.price)||d.options.some(o=>!o.name.trim()||!validPrice(o.price))){u.adminMessage='ปฏิเสธ: ชื่อห้ามว่าง ราคาเมนูและตัวเลือกต้อง ≥ 0';return render();}if(d.pendingName.trim()&&!addOption())return render();if(d.options.length>10){u.adminMessage='ปฏิเสธ: ตัวเลือกได้ 0–10 รายการ';return render();}
 const id=u.adminId==='new'?'m'+String(s.nextMenu).padStart(2,'0'):u.adminId;const removed=s.mappings.filter(m=>m.menu_id===id&&m.scope==='option'&&!d.options.some(o=>o.id===m.option_id));if(removed.length&&!confirm('ตัวเลือกที่นำออกมีแมปวัตถุดิบ บันทึกแล้วจะลบแมปของตัวเลือกเหล่านี้ ยืนยันหรือไม่?')){u.adminMessage='ยกเลิกบันทึก';return render();}
 const m={id,name:d.name.trim(),price:cents(d.price)/100,image:d.image,available:d.available,options:d.options.map(o=>({id:o.id,name:o.name.trim(),price:cents(o.price)/100}))};if(u.adminId==='new'){s.nextMenu++;s.menus.push(m);}else{s.menus[s.menus.findIndex(x=>x.id===id)]=m;}s.mappings=s.mappings.filter(x=>!removed.includes(x));u.adminMessage='บันทึก '+m.name+' ('+id+') แล้ว ยอดออเดอร์เดิมคงเดิม';loadDraft(id);render();}
function deleteMenu(){if(!can('manager'))return deny();const m=s.menus.find(m=>m.id===u.adminId);if(!m)return;const mapped=s.mappings.some(x=>x.menu_id===m.id);if(!confirm(mapped?'เมนู '+m.name+' มีการแมปวัตถุดิบ: ลบเมนูแล้วจะลบแมปทั้งหมดของเมนูและตัวเลือกด้วย ยอดออเดอร์เก่าคงเดิม ยืนยันลบหรือไม่?':'ยืนยันลบเมนู '+m.name+' หรือไม่? ยอดออเดอร์เก่าคงเดิม')){u.adminMessage='ยกเลิกการลบเมนูและแมป';return render();}s.menus=s.menus.filter(x=>x.id!==m.id);s.mappings=s.mappings.filter(x=>x.menu_id!==m.id);u.adminMessage='ลบ '+m.name+' และแมปที่เกี่ยวข้องแล้ว';loadDraft('new');render();}
function saveMapping(){if(!can('manager'))return deny();const m=s.menus.find(x=>x.id===u.mappingMenu),ingredient=s.ingredients.find(x=>x.id===u.mappingIngredient);if(!m||!ingredient||(u.mappingScope==='option'&&!m.options.some(x=>x.id===u.mappingOption))){u.mappingMessage='ปฏิเสธ: ต้องเลือกเมนู/ตัวเลือกที่บันทึกแล้วและวัตถุดิบที่มีอยู่';return render();}const map={menu_id:m.id,ingredient_id:ingredient.id,scope:u.mappingScope,option_id:u.mappingScope==='option'?u.mappingOption:null};if(!s.mappings.some(x=>x.menu_id===map.menu_id&&x.ingredient_id===map.ingredient_id&&x.scope===map.scope&&x.option_id===map.option_id))s.mappings.push(map);u.mappingMessage='บันทึกความสัมพันธ์แล้ว มีผลต่อการปิด/เปิดจำลองทันที';render();}
function saveAccount(){if(!can('manager'))return deny();const name=val('account-username').trim(),pin=val('account-pin'),role=val('account-role');if(!/^[\p{L}\p{N}]{3,20}$/u.test(name)||!/^\d{4,6}$/.test(pin)||!['kitchen','front','manager'].includes(role)){u.accountMessage='ปฏิเสธ: ชื่อผู้ใช้ต้องเป็นตัวอักษร/ตัวเลข 3–20 ตัว และ PIN ตัวเลข 4–6 หลัก';tid('account-message').textContent=u.accountMessage;return;}if(s.accounts.some(a=>a.username.toLowerCase()===name.toLowerCase())){u.accountMessage='ปฏิเสธ: ชื่อผู้ใช้นี้มีอยู่แล้ว';tid('account-message').textContent=u.accountMessage;return;}s.accounts.push({id:name,username:name,pin,role,failures:0,lockedUntil:0});u.accountMessage='สร้างบัญชีจำลอง '+name+' แล้ว';render();}
async function uploadImage(file){if(!can('manager')||!u.draft)return;const d=u.draft,version=epoch;d.imageError='';if(!file){d.imageLoading=false;return;}if(!/\.(jpe?g|png)$/i.test(file.name)||!['image/jpeg','image/png'].includes(file.type)||file.size>2000000){d.imageError='ปฏิเสธรูป: ต้องเป็น jpg/png ไม่เกิน 2 MB (2,000,000 ไบต์ใน mock)';return render();}d.imageLoading=true;render();try{const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('อ่านไฟล์ไม่สำเร็จ'));reader.readAsDataURL(file);});const bytes=new Uint8Array(await file.slice(0,8).arrayBuffer());const png=bytes.length===8&&[137,80,78,71,13,10,26,10].every((b,i)=>bytes[i]===b);const jpg=bytes[0]===255&&bytes[1]===216&&bytes[2]===255;if((file.type==='image/png'&&!png)||(file.type==='image/jpeg'&&!jpg))throw new Error('ข้อมูลไฟล์ไม่ตรง jpg/png');await new Promise((resolve,reject)=>{const img=new Image();img.onload=resolve;img.onerror=()=>reject(new Error('รูปเสียหรือเปิดไม่ได้'));img.src=data;});if(epoch!==version||u.draft!==d||!can('manager'))return;d.image=data;d.imageLoading=false;d.imageError='';render();}catch(e){if(epoch!==version||u.draft!==d)return;d.imageLoading=false;d.imageError='ปฏิเสธรูป: '+e.message;render();}}
// Input events update only draft data; text fields retain caret and keyboard focus.
document.addEventListener('input',e=>{if(!can('manager')||!u.draft)return;const fields={'admin-menu-name':'name','admin-menu-price':'price','admin-option-name':'pendingName','admin-option-price':'pendingPrice'};const key=fields[e.target.dataset.testid];if(key)u.draft[key]=e.target.value;if(e.target.dataset.draftOption!==undefined){const o=u.draft.options[Number(e.target.dataset.draftOption)];if(o)o[e.target.dataset.field]=e.target.value;}});
document.addEventListener('change',e=>{const t=e.target,id=t.dataset.testid;if(id==='staff-user'){u.loginUser=t.value;return;}if(id==='order-mode'){u.mode=t.value;u.selectedMenu=null;u.selectedOptions=[];u.orderMessage='';if(u.mode==='takeaway'){u.takeawayOpened=true;ensureSlot();}render();}else if(id==='table-select'){u.table=t.value;}else if(id==='pickup-slot'){u.slot=slots().find(x=>x.value===t.value)?.t;}else if(t.dataset.option){const option=t.dataset.option;if(t.checked&&!u.selectedOptions.includes(option))u.selectedOptions.push(option);else if(!t.checked)u.selectedOptions=u.selectedOptions.filter(x=>x!==option);render();}else if(id==='ingredient-select'&&can('kitchen')){u.ingredient=t.value;render();}else if(id==='front-table-select'&&can('front')){u.frontTable=t.value;render();}else if(id==='toggle-promptpay'&&can('manager')){s.promptpay=t.checked;render();}else if(id==='admin-menu-select'&&can('manager')){loadDraft(t.value);u.adminMessage='';render();}else if(id==='admin-menu-image'){uploadImage(t.files[0]);}else if(t.id==='admin-available'&&can('manager')){u.draft.available=t.checked;}else if(id?.startsWith('mapping-')&&can('manager')){const fields={'mapping-menu':'mappingMenu','mapping-scope':'mappingScope','mapping-option':'mappingOption','mapping-ingredient':'mappingIngredient'};if(fields[id]){u[fields[id]]=t.value;render();}}});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='login-form')login();});
document.addEventListener('click',e=>{const b=e.target.closest('button[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,id=b.dataset.id;
 if(a==='reset')return reset();if(a==='role')return selectRole(b.dataset.role);if(a==='advance'){s.now+=Number(b.dataset.minutes)*60000;if(s.takeawayDay!==day()){s.takeawayDay=day();s.takeawaySequence=0;}render();return;}if(a==='logout'){epoch++;u.user=null;u.page='';u.auth='ออกจากระบบจำลองแล้ว';history.replaceState(null,'',location.pathname+location.search);return render();}if(a==='nav')return navigate(b.dataset.page);
 if(['open-menu','select-menu','add-item','remove-cart','submit-order','cash','promptpay'].includes(a)&&u.role!=='customer')return;
 if(a==='open-menu')return openMenu();if(a==='select-menu'){u.selectedMenu=id;u.selectedOptions=[];return render();}if(a==='add-item')return addItem();if(a==='remove-cart'){currentCart().splice(Number(id),1);return render();}if(a==='submit-order')return submitOrder();if(a==='cash'||a==='promptpay')return choosePayment(a,id);
 if(a==='next-status'){if(!can('kitchen'))return deny();const o=s.orders.find(x=>x.id===Number(id));if(o&&o.status<2){o.status++;s.statusEvents.push({order_id:o.id,status:statuses[o.status],actor:u.user.username,at:iso()});}return render();}if(a==='stock'){if(!can('kitchen'))return deny();const i=s.ingredients.find(i=>i.id===u.ingredient);if(i)i.available=b.dataset.available==='true';return render();}
 if(a==='confirm-slip'||a==='receive-cash')return confirmPayment(id,a==='confirm-slip'?'slip':'cash');if(a==='close-table'||a==='front-open'){if(!can('front'))return deny();if(a==='front-open'){const x=openTable(u.frontTable);u.frontMessage='เปิดโต๊ะ '+u.frontTable+' · '+x.id;}else{const x=s.sessions.find(x=>x.table_id===u.frontTable&&x.state==='open');if(x){x.state='closed';x.closed_at=iso();x.cart=[];u.frontMessage='ปิดโต๊ะ '+u.frontTable+' · เก็บ '+x.id+' ในประวัติแล้ว';}else u.frontMessage='โต๊ะนี้ไม่มีรอบที่เปิดอยู่';}return render();}
 if(['add-option','remove-option','remove-image','save-menu','delete-menu','save-mapping','save-account'].includes(a)&&!can('manager'))return deny();
 if(a==='add-option'){addOption();return render();}if(a==='remove-option'){u.draft.options.splice(Number(id),1);return render();}if(a==='remove-image'){u.draft.image=null;u.draft.imageError='';return render();}if(a==='save-menu')return saveMenu();if(a==='delete-menu')return deleteMenu();if(a==='save-mapping')return saveMapping();if(a==='save-account')return saveAccount();
});
window.addEventListener('hashchange',handleRoute);window.addEventListener('popstate',handleRoute);
const initialHash=location.hash;reset();if(initialHash){history.replaceState(null,'',initialHash);handleRoute();}
})();
